// Lista spółek pochodzi z węzła "Lista spółek (edytuj)" — edytuj TAM, nie w kodzie.
const raw = $('Lista spółek (edytuj)').first().json.tickers || '';
const WIG20 = String(raw).split(',').map((s) => s.trim().toUpperCase()).filter(Boolean);
if (WIG20.length === 0) { throw new Error('Pusta lista spółek — uzupełnij węzeł "Lista spółek (edytuj)"'); }
const base = 'http://stock-api:8000';
const H = this.helpers;
function sleep(ms) { return new Promise((r) => setTimeout(r, ms)); }
// Pobieramy SEKWENCYJNIE — równoległość wywala yfinance (401 "Invalid Crumb").
// 1 retry z backoffem na wypadek chwilowej blokady. ~70s na całe WIG20.
async function g(path) {
  for (let attempt = 0; attempt < 2; attempt++) {
    try { return await H.httpRequest({ url: base + path, json: true, timeout: 60000 }); }
    catch (e) {
      if (attempt === 0) { await sleep(1200); continue; }
      return { error: String((e && e.message) || e) };
    }
  }
}
const macro = await g('/macro');
const spolki = [];
for (const t of WIG20) {
  const technical = await g(`/technical/${t}`);
  const sentiment = await g(`/sentiment/${t}`);
  const speculator = await g(`/speculator/${t}`);
  spolki.push({ ticker: t, technical, sentiment, speculator });
}
const kiedy = new Date().toLocaleString('pl-PL', { timeZone: 'Europe/Warsaw' });
const prompt =
  `Dzienny przegląd WIG20. Data/godzina: ${kiedy}.\n\n` +
  `KONTEKST MAKRO:\n${JSON.stringify(macro, null, 1)}\n\n` +
  `DANE SPÓŁEK (technical, sentiment, speculator):\n${JSON.stringify(spolki, null, 1)}`;
return [{ json: { prompt, count: spolki.length } }];
